  "recovered_c": "uint64_t fn_13(uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  uint8_t k[8];\n  uint8_t s[256];\n  uint8_t *in_local = in;\n  size_t len_local = len;\n  uint8_t *out_local = out;\n  size_t out_cap_local = out_cap;\n  uint8_t t;\n  uint i;\n  uint j;\n  size_t n;\n\n  if (out_cap_local < len_local) {\n    return 0xFFFFFFFFFFFFFFFF;\n  }\n\n  for (i = 0; i < 8; i++) {\n    k[i] = (uint8_t)(arg >> ((byte)(i << 3) & 0x3f));\n  }\n\n  for (i = 0; i < 0x100; i++) {\n    s[i] = (uint8_t)i;\n  }\n\n  for (i = 0; i < 0x100; i++) {\n    j = (k[i & 7] ^ i) + s[i] + j & 0xff;\n    t = s[i];\n    s[i] = s[j];\n    s[j] = t;\n  }\n\n  j = 0;\n  i = 0;\n  for (n = 0; n < len_local; n++) {\n    i = i + 1 & 0xff;\n    j = j + s[i] & 0xff;\n    t = s[i];\n    s[i] = s[j];\n    s[j] = t;\n    out_local[n] = in_local[n] ^ s[(uint)s[j] + (uint)s[i] & 0xff];\n  }\n\n  return len_local;\n}"
